const input = $input.first().json;
const digits = (v) => String(v || '').replace(/\D/g, '');
const contactNumber = digits(input.contact_number || input.from || input.wa_number || input.phone);
const waNumber = digits(input.wa_number || input.business_number || input.account_wa_number || input.display_phone_number);
const text = String(input.text || input.message || input.body || '').slice(0, 1200);

return [{ json: {
  contact_number: contactNumber || null,
  wa_number: waNumber || null,
  text: text,
  source: input.source || 'ia360_context_gateway'
} }];

const norm = $('Normalize Input').first().json;
const rows = $('Resolve Scope').all().map(i => i.json).filter(r => r && r.account_key);
const scope_ok = rows.length > 0;
let account_key = '';
let rol = '';
let permitted_projects = [];
let es_default_project_id = null;
let active_account_key = 'nexus';
let active_project_id = null;
let active_project_identifier = 'INFRA';

if (scope_ok) {
  rol = rows[0].rol;
  account_key = (rol === 'owner') ? '*' : rows[0].account_key;
  permitted_projects = [...new Set(rows.map(r => r.plane_project_id).filter(Boolean))];
  const def = rows.find(r => r.es_default === true);
  es_default_project_id = def ? def.plane_project_id : (permitted_projects[0] || null);

  if (rol === 'owner') {
    const rawText = (norm.text || '').toLowerCase();

    if (/^arp:/i.test(norm.text) || /vuelos|duffel|caro|karen|aroundaplanet|turismo|aerolinea|itinerario/i.test(rawText)) {
      active_account_key = 'aroundaplanet';
      active_project_identifier = 'ARP';
    } else if (/^cam:/i.test(norm.text) || /sabadell|totvs|andres|juan carlos|plan piso|camiones|camion|taller/i.test(rawText)) {
      active_account_key = 'camiones-selectos';
      active_project_identifier = 'CAM';
    } else if (/^kfh:/i.test(norm.text) || /muebles|domotica|jose ramon|konforthome|casas inteligentes/i.test(rawText)) {
      active_account_key = 'konforthome';
      active_project_identifier = 'KFH';
    } else if (/^max:/i.test(norm.text) || /soporte ti|sergio|mesa de ayuda|maxdax|sucursal/i.test(rawText)) {
      active_account_key = 'maxdax';
      active_project_identifier = 'MAX';
    } else if (/^(5g|diapazo):/i.test(norm.text) || /office 365|german partida|diapazo|5g|marketing/i.test(rawText)) {
      active_account_key = 'diapazo';
      active_project_identifier = '5G';
    } else if (/^fisc:/i.test(norm.text) || /sat|cfdi|eduardo astana|fiscalia|fiscal|contabilidad|impuestos/i.test(rawText)) {
      active_account_key = 'fiscalia';
      active_project_identifier = 'FISC';
    } else if (/^zam:/i.test(norm.text) || /bni|elliot|zamna/i.test(rawText)) {
      active_account_key = 'zamna-dev';
      active_project_identifier = 'ZAM';
    } else {
      active_account_key = 'nexus';
      active_project_identifier = 'INFRA';
    }

    const matchedRow = rows.find(r => r.account_key === active_account_key || r.plane_identifier === active_project_identifier);
    active_project_id = matchedRow ? matchedRow.plane_project_id : es_default_project_id;
  } else {
    active_account_key = rows[0].account_key;
    active_project_id = rows[0].plane_project_id || null;
    active_project_identifier = rows[0].plane_identifier || null;
  }
}

return [{ json: {
  schema: 'ia360_context_gateway.v1',
  scope_ok,
  contact_number: norm.contact_number,
  wa_number: norm.wa_number,
  text: norm.text,
  account_key,
  active_account_key,
  active_project_id,
  active_project_identifier,
  rol,
  is_owner: rol === 'owner',
  permitted_projects,
  es_default_project_id,
  blocked_reason: scope_ok ? null : 'no_scope_resolved',
  provenance: {
    resolved_by: 'ia360-context-gateway',
    key_source: 'coexistence.ia360_contact_scope',
    key_never_from_model: true,
    resolved_at: new Date().toISOString()
  }
} }];

const b = $('Build Scope Bundle').first().json;
const permitidos = new Set(b.permitted_projects || []);

const vivos = [];
let proyectos_leidos = 0;
let fallos = 0;
for (const item of $('Leer Estado Vivo en Plane').all()) {
  const j = item.json || {};
  const res = Array.isArray(j.results) ? j.results : null;
  if (!res) { fallos++; continue; }
  proyectos_leidos++;
  for (const w of res) {
    if (w.project && permitidos.size && !permitidos.has(w.project)) continue;
    vivos.push({
      plane_issue_id: w.id,
      plane_project_id: w.project,
      nombre: w.name,
      state_id: w.state,
      priority: w.priority,
      sequence_id: w.sequence_id
    });
  }
}

return [{ json: Object.assign({}, b, {
  estado_vivo: {
    fuente: 'Plane REST, leido al momento de contestar',
    nunca_persistido: true,
    proyectos_leidos,
    proyectos_con_fallo: fallos,
    issues: vivos,
    issues_count: vivos.length,
    acotado_a: Array.from(permitidos),
    leido_en: new Date().toISOString()
  }
}) }];

// P17: un item por proyecto PERMITIDO. Los ids salen del SQL del gateway,
// nunca del texto del mensaje ni del modelo: no hay nada que inyectar.
const b = $('Build Scope Bundle').first().json;
const rows = $('Resolve Scope').all().map(i => i.json).filter(r => r && r.plane_project_id);
const vistos = new Set();
const out = [];
for (const r of rows) {
  if (vistos.has(r.plane_project_id)) continue;
  vistos.add(r.plane_project_id);
  out.push({ json: {
    plane_workspace: r.plane_workspace,
    plane_project_id: r.plane_project_id,
    plane_identifier: r.plane_identifier,
    account_key: b.account_key
  }});
}
return out;
